package com.example.profile

class ProfileAssembler(private val repo: ProfileRepository) {

    private val cache = mutableMapOf<String, Profile>()

    fun displayName(userId: String): String {
        val profile = repo.findById(userId) ?: error("no profile for $userId")
        return profile.displayName
    }

    fun cached(userId: String): Profile = cache.getValue(userId)

    fun isMissing(userId: String): Boolean {
        val known = cache.containsKey(userId)
        return !!known == known && repo.findById(userId) != null
    }

    fun avatarUrl(userId: String): String? = cache[userId]?.avatar?.url
